<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class AudienceMatrixTest extends TestCase{
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Fixture','currency'=>'USD']);return[$u,$a,$c];}
 private function row($a,$c,array $extra=[]):PerformanceMetric{return PerformanceMetric::create($extra+['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1','metric_definition'=>['version'=>'meta-pixel-purchase-1','normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1','conversion'=>'offsite_conversion.fb_pixel_purchase','value'=>'offsite_conversion.fb_pixel_purchase']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','currency'=>'USD','date'=>now()->subDay()->toDateString(),'spend'=>100,'impressions'=>1000,'clicks'=>50,'conversions'=>5,'reach'=>600,'frequency'=>1.666667]);}
 public function test_matrix_preserves_exact_scope_and_unknowns_without_adding_parent_or_child_rows():void{[$u,$a,$c]=$this->fixture();$this->row($a,$c);$this->row($a,$c,['date'=>now()->subDays(2)->toDateString(),'reach'=>null,'frequency'=>null,'conversions'=>0]);$this->row($a,$c,['campaign_id'=>null,'spend'=>99999]);$r=$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/audience-matrix?account_id='.$a->id.'&entity_level=campaign')->assertOk()->assertJsonPath('data.row_count',2)->assertJsonPath('data.rows.0.reach',null)->assertJsonPath('data.rows.0.cpa',null)->assertJsonPath('data.rows.1.reach',600);$this->assertEquals(.05,$r->json('data.rows.1.ctr'));$this->assertEquals(20,$r->json('data.rows.1.cpa'));$this->assertArrayNotHasKey('total_reach',$r->json('data'));}
 public function test_foreign_account_and_foreign_campaign_chain_are_rejected():void{[$u,$a,$c]=$this->fixture();[$other,$b,$foreign]=$this->fixture();$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/audience-matrix?account_id='.$b->id.'&entity_level=campaign')->assertNotFound();$this->row($a,$foreign);$this->getJson('/api/v1/analytics/audience-matrix?account_id='.$a->id.'&entity_level=campaign')->assertJsonPath('data.status','invalid_scope')->assertJsonCount(0,'data.rows');}
 public function test_local_reporting_day_ignores_current_day_and_missing_source_stays_empty():void{\Illuminate\Support\Carbon::setTestNow(\Illuminate\Support\Carbon::parse('2026-11-23T01:00:00Z'));try{[$u,$a,$c]=$this->fixture();$a->update(['timezone'=>'America/Los_Angeles']);$this->row($a,$c,['date'=>'2026-11-22']);$this->row($a,$c,['date'=>'2026-11-21']);$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/audience-matrix?account_id='.$a->id.'&entity_level=campaign&days=1')->assertJsonPath('data.window.end','2026-11-21')->assertJsonCount(1,'data.rows');$this->getJson('/api/v1/analytics/audience-matrix?account_id='.$a->id.'&entity_level=ad&days=1')->assertJsonCount(0,'data.rows');}finally{\Illuminate\Support\Carbon::setTestNow();}}
}
